from pathlib import Path
import numpy as np, pickle, scipy.io as sio, h5py
base = Path('/app/data')
files = sorted([p for p in base.rglob('*') if p.is_file()])
for p in files:
    print('\n===', p, '===')
    suf = p.suffix.lower()
    try:
        if suf == '.npy':
            arr = np.load(p, allow_pickle=True)
            if isinstance(arr, np.ndarray):
                print('npy dtype=', arr.dtype, 'shape=', arr.shape)
                if arr.dtype == object and arr.shape == ():
                    obj = arr.item()
                    print('scalar object type=', type(obj))
                    if isinstance(obj, dict):
                        print('dict keys=', list(obj.keys())[:20])
            else:
                print(type(arr))
        elif suf == '.npz':
            z = np.load(p, allow_pickle=True)
            print('npz keys=', list(z.keys()))
            for k in list(z.keys())[:10]:
                v = z[k]
                print(' ', k, getattr(v, 'shape', None), getattr(v, 'dtype', None))
        elif suf == '.pkl':
            obj = pickle.load(open(p, 'rb'))
            print('pkl type=', type(obj))
            if isinstance(obj, dict):
                print('dict keys=', list(obj.keys())[:20])
        elif suf == '.mat':
            try:
                m = sio.loadmat(p)
                print('mat keys=', [k for k in m.keys() if not k.startswith('__')][:20])
            except Exception:
                with h5py.File(p, 'r') as f:
                    print('h5/mat keys=', list(f.keys())[:20])
        elif suf in ['.csv', '.tsv', '.txt']:
            print(p.read_text(errors='ignore')[:1000])
        else:
            print('unknown suffix', suf)
    except Exception as e:
        print('ERROR', repr(e))
